"from bs4 import BeautifulSoup\nimport re\n\nwith open('tests/workday/Systems Software Engineer - New College Grad 2026.htm', 'r', encoding='utf-8', errors='ignore') as f:\n    soup = BeautifulSoup(f.read(), 'html.parser')\n\nprint(\"=== 1. FIELD OF STUDY ===\")\nfor el in soup.find_all(lambda tag: tag.name in ['input', 'button', 'div', 'select'] and any(k in (tag.get('id', '') + tag.get('data-automation-id', '') + tag.get('aria-label', '')).lower() for k in ['fieldofstudy', 'field-of-study', 'study'])):\n    print(f\"Tag: {el.name}, id='{el.get('id')}', aid='{el.get('data-automation-id')}', role='{el.get('role')}', class='{el.get('class')}', aria-label='{el.get('aria-label')}'\")\n\nprint(\"\\n=== 2. SKILLS ===\")\nfor el in soup.find_all(lambda tag: tag.name in ['input', 'button', 'div', 'textarea'] and 'skill' in (tag.get('id', '') + tag.get('data-automation-id', '') + tag.get('aria-label', '')).lower()):\n    print(f\"Tag: {el.name}, id='{el.get('id')}', aid='{el.get('data-automation-id')}', role='{el.get('role')}', class='{el.get('class')}', aria-label='{el.get('aria-label')}'\")\n\nprint(\"\\n=== 3. RESUME / FILE UPLOAD ===\")\nfor el in soup.find_all(lambda tag: tag.name in ['input', 'button', 'div'] and any(k in (tag.get('id', '') + tag.get('data-automation-id', '') + tag.get('type', '')).lower() for k in ['file', 'resume', 'upload', 'attachment', 'drop'])):\n    print(f\"Tag: {el.name}, type='{el.get('type')}', id='{el.get('id')}', aid='{el.get('data-automation-id')}', class='{el.get('class')}'\")\n"